    35→		error = '';
    36→		try {
    37→			const data = await fetchSessions();
    38→			// AC: @ui-session-history ac-1 — sorted by most recent first (daemon returns pre-sorted)
    39→			sessions = data.items;
    40→		} catch (err) {
    41→			error = err instanceof Error ? err.message : 'Failed to load sessions';
    42→		} finally {
    43→			loading = false;
    44→		}
    45→	}
    46→
    47→	function statusColor(status: string): string {
    48→		switch (status) {
    49→			case 'active':
    50→				return 'bg-status-in-progress text-status-in-progress-fg';
    51→			case 'completed':
    52→				return 'bg-status-completed text-status-completed-fg';
    53→			case 'failed':
    54→				return 'bg-status-blocked text-status-blocked-fg';
    55→			case 'abandoned':
    56→				return 'bg-status-needs-work text-status-needs-work-fg';
    57→			case 'timed_out':
    58→				return 'bg-status-pending text-status-pending-fg';
    59→			default:
    60→				return 'bg-status-cancelled text-status-cancelled-fg';
    61→		}
    62→	}
    63→
    64→	// Load sessions when project is ready and reload on project change.
    65→	// Gates on isProjectInitialized() to prevent loading with wrong/missing project context.
    66→	$effect(() => {
    67→		const version = getProjectVersion();
    68→		const ready = isProjectInitialized();
    69→		if (!ready) return;
    70→		loadSessions();
    71→	});
    72→</script>
