     8→	import { page } from '$app/stores';
     9→	import { onMount, onDestroy } from 'svelte';
    10→	import type { SessionDetail, SessionEvent as SessionEventType } from '$lib/api';
    11→	import { fetchSession, fetchSessionEvents } from '$lib/api';
    12→	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
    13→	import type { BroadcastEvent } from '@kynetic-ai/shared';
    14→	import { parseEventsToBlocks, accumulateStreamingText, getLastSeq, type DisplayBlock } from '$lib/components/session/session-utils';
    15→	import SessionStream from '$lib/components/session/SessionStream.svelte';
    16→	import SessionContextPanel from '$lib/components/session/SessionContextPanel.svelte';
    17→	import SessionStreamSkeleton from '$lib/components/session/SessionStreamSkeleton.svelte';
    18→	import ArrowLeft from '@lucide/svelte/icons/arrow-left';
    19→	import { base } from '$app/paths';
    20→
    21→	let sessionId = $derived($page.params.id);
    22→
    23→	let session = $state<SessionDetail | null>(null);
    24→	let events = $state<SessionEventType[]>([]);
    25→	let blocks = $state<DisplayBlock[]>([]);
    26→	let loading = $state(true);
    27→	let error = $state('');
    28→
    29→	// AC: @ui-session-stream ac-2 — Live streaming state
    30→	let streamingText = $state('');
    31→	let isLive = $derived(session?.status === 'active');
    32→	let lastSeq = $state(-1);
    33→	let refreshTimer: ReturnType<typeof setInterval> | undefined;
    34→
    35→	async function loadSession() {
    36→		loading = true;
    37→		error = '';
    38→		try {
    39→			const [sessionData, eventsData] = await Promise.all([
    40→				fetchSession(sessionId),
    41→				fetchSessionEvents(sessionId)
    42→			]);
    43→			session = sessionData;
    44→			events = eventsData.events;
    45→			blocks = parseEventsToBlocks(events);
    46→			lastSeq = getLastSeq(events);
    47→		} catch (err) {
    48→			error = err instanceof Error ? err.message : 'Failed to load session';
    49→		} finally {
    50→			loading = false;
    51→		}
    52→	}
    53→
    54→	// AC: @ui-session-stream ac-2 — Periodic structured refresh for live sessions
    55→	async function refreshEvents() {
    56→		if (!isLive) return;
    57→		try {
    58→			const eventsData = await fetchSessionEvents(sessionId, lastSeq);
    59→			if (eventsData.events.length > 0) {
    60→				events = [...events, ...eventsData.events];
    61→				blocks = parseEventsToBlocks(events);
    62→				lastSeq = getLastSeq(events);
    63→				// Clear streaming text when we get structured data
    64→				streamingText = '';
    65→			}
    66→
    67→			// Also refresh session metadata to detect status changes
    68→			const sessionData = await fetchSession(sessionId);
    69→			session = sessionData;
    70→		} catch {
    71→			// Ignore refresh errors — will retry on next interval
    72→		}
    73→	}
    74→
    75→	// AC: @ui-session-stream ac-2 — WebSocket handler for live text chunks
    76→	function handleAgentEvent(event: BroadcastEvent) {
    77→		// Uses extracted utility for session-filtered text accumulation
    78→		streamingText = accumulateStreamingText(streamingText, event, sessionId);
    79→
    80→		if (event.event === 'agent_invocation') {
    81→			const data = event.data as { session_id?: string; status?: string };
    82→			if (data.session_id === sessionId) {
    83→				// Refresh on invocation state changes
    84→				refreshEvents();
    85→			}
    86→		}
    87→	}
    88→
    89→	onMount(() => {
    90→		loadSession();
    91→
    92→		// Subscribe to agent events for live streaming
    93→		subscribe(['agents']);
    94→		on('agents', handleAgentEvent);
    95→
    96→		// AC: @ui-session-stream ac-2 — Periodic refresh (every 3s for live sessions)
    97→		refreshTimer = setInterval(() => {
    98→			if (isLive) {
    99→				refreshEvents();
   100→			}
   101→		}, 3000);
   102→	});
   103→
   104→	onDestroy(() => {
   105→		off('agents', handleAgentEvent);
   106→		unsubscribe(['agents']);
   107→		if (refreshTimer) clearInterval(refreshTimer);
   108→	});
   109→</script>
   110→
   111→<div class="flex flex-col h-full">
   112→	<!-- Header -->
   113→	<div class="flex items-center gap-3 px-4 py-3 border-b flex-shrink-0">
   114→		<a
   115→			href="{base}/sessions"
   116→			class="text-muted-foreground hover:text-foreground transition-colors"
   117→			title="Back to sessions"
   118→		>
   119→			<ArrowLeft class="size-4" />
   120→		</a>
   121→		<div>
   122→			<h1 class="text-lg font-semibold">
   123→				Session
   124→				{#if session}
   125→					<span class="font-mono text-sm text-muted-foreground ml-1">{session.id.slice(0, 8)}</span>
   126→				{/if}
   127→			</h1>
   128→			{#if session}
   129→				<p class="text-xs text-muted-foreground">
   130→					{session.agent_type}
   131→					{#if isLive}
   132→						<span class="ds-session-active-dot size-1.5 rounded-full bg-status-completed inline-block ml-1"></span>
   133→						<span class="text-status-completed">Live</span>
   134→					{/if}
   135→				</p>
   136→			{/if}
   137→		</div>
   138→	</div>
   139→
   140→	<!-- Error -->
   141→	{#if error}
   142→		<div class="mx-4 mt-4 bg-destructive/10 text-destructive p-4 rounded-lg" role="alert" data-testid="session-error">
   143→			{error}
   144→		</div>
   145→	{/if}
   146→
   147→	<!-- Loading skeleton -->
   148→	{#if loading}
   149→		<SessionStreamSkeleton />
   150→	{:else if session}
   151→		<!-- Main content: context panel + stream -->
   152→		<div class="flex flex-1 min-h-0">
   153→			<!-- AC: @ui-session-stream ac-4 — Context panel with spec context, files, budget -->
   154→			<SessionContextPanel {session} {blocks} />
   155→
   156→			<!-- AC: @ui-session-stream ac-1, ac-2, ac-3 — Event stream -->
   157→			<SessionStream {blocks} {isLive} {streamingText} />
   158→		</div>
   159→	{/if}
   160→</div>
   161→
   162→<style>
   163→	@keyframes session-pulse {
   164→		0%, 100% { opacity: 1; }
   165→		50% { opacity: 0.4; }
   166→	}
   167→	:global(.ds-session-active-dot) {
   168→		animation: session-pulse 2s ease-in-out infinite;
   169→	}
   170→	@media (prefers-reduced-motion: reduce) {
   171→		:global(.ds-session-active-dot) {
   172→			animation: none;
   173→		}
   174→	}
   175→</style>
   176→
```

